// A painted still with water-only scanline displacement: the buildings remain perfectly still.
export class Illustration {
 constructor(city,canvas,water){this.city=city;this.canvas=canvas;this.ctx=canvas.getContext('2d');this.water=water;this.image=null;this.previous=null;this.token=0;this.transitionStart=0;this.cache=new Map();this.visible=true;this.failed=false;new ResizeObserver(()=>{this.resize();this.render(performance.now()/1000,false);}).observe(canvas.parentElement);this.resize();}
 resize(){const r=this.canvas.parentElement.getBoundingClientRect();this.w=r.width;this.h=r.height;this.dpr=Math.min(devicePixelRatio,1.5);this.canvas.width=Math.round(this.w*this.dpr);this.canvas.height=Math.round(this.h*this.dpr);}
 async load(url,animate=true){if(url===this.url)return;this.url=url;const token=++this.token;let image=this.cache.get(url);try{if(!image){image=new Image();image.src=url;await image.decode();this.cache.set(url,image);}if(token!==this.token)return;this.previous=animate?this.image:null;this.image=image;this.failed=false;this.transitionStart=performance.now()/1000;this.render(this.transitionStart,false);}catch(error){if(token!==this.token)return;this.failed=true;this.canvas.dispatchEvent(new CustomEvent('art-error',{detail:{url}}));console.warn('Illustration unavailable',url);}}
 draw(image,t,animated,alpha=1){const {ctx,w,h,dpr}=this,iw=image.naturalWidth,ih=image.naturalHeight,scale=Math.max(w/iw,h/ih),dw=iw*scale,dh=ih*scale,focus=this.city==='paris'?.27:.76,dx=(w-dw)*focus,dy=(h-dh)/2;ctx.save();ctx.globalAlpha=alpha;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.drawImage(image,dx,dy,dw,dh);if(animated){ctx.beginPath();const waterY=ih*this.water.start;ctx.moveTo(dx+iw*this.water.left*scale,dy+waterY*scale);ctx.lineTo(dx+dw,dy+waterY*scale);ctx.lineTo(dx+dw,dy+dh);ctx.lineTo(dx+iw*(this.water.foreground?.39:0)*scale,dy+dh);if(this.water.foreground)ctx.lineTo(dx+iw*.24*scale,dy+ih*.88*scale);ctx.closePath();ctx.clip();const step=2;for(let sy=Math.floor(waterY);sy<ih-step;sy+=step){const depth=(sy-waterY)/(ih-waterY);const shift=(Math.sin(sy*.045+t*.72)*2.2+Math.sin(sy*.11-t*.4)*1.3)*depth;ctx.drawImage(image,0,sy,iw,step,dx+shift*scale,dy+sy*scale,dw,step*scale+.4);}}ctx.restore();}
 render(t,animated){if(!this.visible||!this.image||!this.ctx)return;const blend=animated?Math.min(1,(t-this.transitionStart)/1.7):1;this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);if(this.previous&&blend<1)this.draw(this.previous,t,animated,1);this.draw(this.image,t,animated,blend);if(blend>=1)this.previous=null;}
}
